import React, { useState } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Button } from "react-bootstrap";

function History() {
  const [cameraId, setCameraId] = useState("CAM01");
  const [date, setDate] = useState("");
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [data, setData] = useState({ labels: [], series: [] });

  // ฟังก์ชันช่วยแสดงวันที่แบบไทย (วัน เดือน ปี พ.ศ.)
  const formatThaiDate = (dateStr) => {
    if (!dateStr) return "";
    return new Date(dateStr).toLocaleDateString('th-TH', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  const fetchHistory = async () => {
    if (!date) return alert("กรุณาเลือกวันที่ก่อนครับ");
    
    try {
      const response = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&date=${date}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await response.json();
      
      // ปรับแต่งตัวเลขเวลาบนกราฟให้มี "น." ต่อท้าย (แบบไทย)
      const thaiLabels = result.labels.map(label => label + " น.");
      
      setData({
        labels: thaiLabels,
        series: result.series
      });
    } catch (err) {
      console.error("Error:", err);
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">ค้นหาข้อมูลย้อนหลัง (รูปแบบไทย)</Card.Title>
            </Card.Header>
            <Card.Body>
              <Row>
                {/* เลือกสถานี */}
                <Col md="3">
                  <Form.Group>
                    <label>เลือกจุดจอดรถ/สาย</label>
                    <Form.Control as="select" value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                      <option value="CAM01">คณะวิศวกรรมศาสตร์ (CAM01)</option>
                      <option value="CAM02">คณะวิทยาศาสตร์ (CAM02)</option>
                      <option value="CAM03">คณะศิลปศาสตร์ (CAM03)</option>
                      <option value="CAM04">หอพัก PKY (CAM04)</option>
                    </Form.Control>
                  </Form.Group>
                </Col>
                {/* เลือกวันที่ */}
                <Col md="3">
                  <Form.Group>
                    <label>วันที่ (ว/ด/ป พ.ศ.)</label>
                    <Form.Control type="date" value={date} onChange={(e) => setDate(e.target.value)} />
                  </Form.Group>
                </Col>
                {/* เลือกเวลาเริ่มต้น */}
                <Col md="2">
                  <Form.Group>
                    <label>ตั้งแต่เวลา (น.)</label>
                    <Form.Control type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} />
                  </Form.Group>
                </Col>
                {/* เลือกเวลาสิ้นสุด */}
                <Col md="2">
                  <Form.Group>
                    <label>จนถึงเวลา (น.)</label>
                    <Form.Control type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} />
                  </Form.Group>
                </Col>
                {/* ปุ่มค้นหา */}
                <Col md="2" className="d-flex align-items-end">
                  <Button className="btn-fill w-100" variant="info" onClick={fetchHistory}>ดึงข้อมูล</Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* แสดงกราฟเมื่อกดดึงข้อมูลมาแล้ว */}
      {data.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">
                  สถิติจำนวนคนจุด {cameraId} ประจำวันที่ {formatThaiDate(date)}
                </Card.Title>
                <p className="card-category">
                  แสดงข้อมูลตั้งแต่เวลา {startTime} น. ถึง {endTime} น.
                </p>
              </Card.Header>
              <Card.Body>
                <ChartistGraph
                  data={data}
                  type="Line"
                  options={{
                    low: 0,
                    height: "300px",
                    showArea: true,
                    fullWidth: true,
                    axisX: { showGrid: false }
                  }}
                />
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
